'use strict';
(function(root){
const R=root.DCRecipes,C=root.DCCore;let records=[],loaded=false,selectedId='',query='',operation=0;
async function open(h){
 const{esc,header,openModal,toast,download}=h;
 const run=++operation;
 if(!loaded){try{records=(await h.read())||[];records=records.map(R.validate);loaded=true;}catch(e){toast('模板库读取失败：'+e.message);return;}}
 if(run!==operation)return;
 const chosen=h.selection();
 if(!records.some(r=>r.id===selectedId))selectedId=records[0]?.id||'';
 openModal(header('▦ 配方模板库')+`<div class="modal-content recipe-shell"><p class="modal-copy">保存选区，复用手型。模板仅留在此浏览器；跨设备请下载后导入，不会随账号同步。</p><div class="recipe-actions"><button id="recipeCapture" class="primary" ${chosen.length?'':'disabled'}>＋ 保存当前选区（${chosen.length}）</button><button id="recipeImport">↥ 导入模板</button><button id="recipeExportAll" ${records.length?'':'disabled'}>↧ 下载模板库</button><input type="file" id="recipeFile" accept=".json,.zip" multiple hidden></div><div class="recipe-workspace"><div class="recipe-sidebar"><input id="recipeSearch" placeholder="搜索名称 / 标签" value="${esc(query)}" aria-label="搜索配方"><div id="recipeList" role="listbox" aria-label="配方模板"></div><small id="recipeStorage"></small></div><div id="recipeDetail"></div></div></div>`,true);
 async function persist(next){await h.write(next);records=next;}
 function pick(){return records.find(r=>r.id===selectedId);}
 function list(){const term=query.trim().toLowerCase(),items=records.filter(r=>(r.name+' '+r.tags.join(' ')).toLowerCase().includes(term));document.getElementById('recipeList').innerHTML=items.length?items.map(r=>`<button class="recipe-item ${r.id===selectedId?'active':''}" role="option" aria-selected="${r.id===selectedId}" data-recipe-id="${esc(r.id)}"><b>${esc(r.name)}</b><span>${r.notes.length} 音符 · ${esc(r.tags.join(' / ')||'无标签')}</span></button>`).join(''):'<p class="empty-state">'+(records.length?'没有匹配的配方':'先框选音符，再保存第一份配方。')+'</p>';document.getElementById('recipeStorage').textContent=`${records.length} / 500 份 · ${(new TextEncoder().encode(JSON.stringify(records)).length/1024).toFixed(1)} KB / 8 MB`;document.querySelectorAll('[data-recipe-id]').forEach(b=>b.onclick=()=>{selectedId=b.dataset.recipeId;list();detail();});}
 function detail(){const r=pick(),el=document.getElementById('recipeDetail');if(!r){el.innerHTML='<div class="recipe-empty"><span>▦</span><h4>把好用的段落留在手边</h4><p>模板保存相对拍数和原始键位，适用于不同 BPM 的歌曲。</p><p>包含单点、长条与假键，不包含音乐、BPMList 或 Effect。</p></div>';return;}
 const span=C.beatValue(r.span),fake=r.notes.filter(n=>n.end!==null&&C.beatValue(n.end)===C.beatValue(n.beat)).length;
 el.innerHTML=`<form id="recipeEdit"><div class="two-fields"><label class="field">配方名称<input id="recipeName" value="${esc(r.name)}" maxlength="80" required></label><label class="field">标签（逗号分隔）<input id="recipeTags" value="${esc(r.tags.join(', '))}" maxlength="300"></label></div><label class="field">备注<textarea id="recipeDescription" maxlength="600" rows="2">${esc(r.description)}</textarea></label><p class="field-hint">${r.notes.length} 音符 · ${fake} 假键 · 跨度 [${r.span.join(',')}] · 来源 ${esc(r.source.title||'导入模板')} / ${esc(r.source.chart)}</p><canvas id="recipeCanvas" class="recipe-canvas" aria-label="模板六轨示意图"></canvas><div class="button-row"><button type="submit">保存资料</button><button type="button" id="recipeExportOne">下载此配方</button><button type="button" id="recipeRemove" class="danger-text">删除此配方</button></div></form><form id="recipeInsert"><h4>插入当前谱面</h4><div class="two-fields"><label class="field">目标拍位<input id="recipeBeat" value="${esc(JSON.stringify(C.beatParts(h.currentBeat())))}" required></label><label class="field">节奏缩放<select id="recipeScale"><option value="0.25">¼ ×</option><option value="0.5">½ ×</option><option value="1" selected>1 ×</option><option value="2">2 ×</option><option value="4">4 ×</option></select></label><label class="field">镜像<select id="recipeMirror"><option value="">原始键位</option><option value="horizontal">左右</option><option value="vertical">上下</option><option value="rotation">中心</option></select></label><label class="field">重复次数<input id="recipeRepeat" type="number" min="1" max="32" value="1"></label></div><label class="field">每次重复之间的空拍<input id="recipeGap" value="[0,0,4]"></label><p class="field-hint">跨度包含长条尾端；重复边界重叠时增加空拍。整组碰撞会拦截，可撤销插入。</p><button class="primary" type="submit">插入并选中新音符</button></form>`;
 document.getElementById('recipeEdit').onsubmit=async e=>{e.preventDefault();try{const next=R.validate({...r,name:document.getElementById('recipeName').value,tags:document.getElementById('recipeTags').value.split(/[,，]/),description:document.getElementById('recipeDescription').value,updatedAt:Date.now()});const all=records.map(x=>x.id===r.id?next:x);R.merge([],all);await persist(all);toast('配方资料已保存');list();detail();}catch(err){toast(err.message);}};
 document.getElementById('recipeExportOne').onclick=()=>download(JSON.stringify(r,null,2),DCProject.fileName(r.name)+'.dcrecipe.json','application/json');
 document.getElementById('recipeRemove').onclick=()=>{const b=document.getElementById('recipeRemove');if(b.dataset.confirm!=='yes'){b.dataset.confirm='yes';b.textContent='再次点击确认删除';return;}persist(records.filter(x=>x.id!==r.id)).then(()=>{selectedId=records[0]?.id||'';list();detail();document.getElementById('recipeExportAll').disabled=!records.length;}).catch(err=>toast(err.message));};
 document.getElementById('recipeInsert').onsubmit=e=>{e.preventDefault();try{const items=R.instantiate(r,{beat:C.parseBeat(document.getElementById('recipeBeat').value),scale:+document.getElementById('recipeScale').value,mirror:document.getElementById('recipeMirror').value||null,repeat:+document.getElementById('recipeRepeat').value,gap:C.parseBeat(document.getElementById('recipeGap').value)});h.insert(items);document.getElementById('modal').close();toast(`已插入 ${items.length} 个音符，可撤销`);}catch(err){toast(err.message);}};
 requestAnimationFrame(()=>{const canvas=document.getElementById('recipeCanvas');if(!canvas)return;const box=canvas.getBoundingClientRect(),dpr=Math.min(2,devicePixelRatio||1);canvas.width=box.width*dpr;canvas.height=box.height*dpr;const c=canvas.getContext('2d');c.scale(dpr,dpr);const w=box.width,ht=box.height,left=28,top=18,rw=(w-left-10)/6,max=Math.max(1,span),y=b=>top+(ht-top-12)*b/max;c.strokeStyle='#82759555';for(let i=0;i<=6;i++){c.beginPath();c.moveTo(left+i*rw,top);c.lineTo(left+i*rw,ht-10);c.stroke();}c.fillStyle='#a69cae';c.font='10px monospace';for(let i=0;i<6;i++)c.fillText(String(C.LAYOUTS.dancecube[i]+1),left+(i+.5)*rw-3,11);for(const n of r.notes){const x=left+(C.LAYOUTS.dancecube.indexOf(n.lane)+.5)*rw,b=C.beatValue(n.beat),end=n.end===null?null:C.beatValue(n.end);c.fillStyle=end===b?'#e6b96e':'#b78cf5';if(end!==null&&end>b)c.fillRect(x-3,y(b),6,Math.max(1,y(end)-y(b)));c.fillRect(x-7,y(b)-2,14,4);}});
 }
 document.getElementById('recipeSearch').oninput=e=>{query=e.target.value;list();};
 document.getElementById('recipeCapture').onclick=async()=>{try{const r=R.capture(h.selection(),{name:(h.songTitle()||'歌曲')+' · 选区配方',source:h.source()});await persist(R.merge(records,[r]));selectedId=r.id;list();detail();document.getElementById('recipeExportAll').disabled=false;toast('选区已保存为模板');}catch(e){toast(e.message);}};
 document.getElementById('recipeImport').onclick=()=>document.getElementById('recipeFile').click();
 document.getElementById('recipeFile').onchange=async e=>{const files=[...e.target.files];e.target.value='';try{const incoming=[];if(files.reduce((sum,f)=>sum+f.size,0)>R.LIMITS.bytes)throw Error('一次导入最多 8 MB');for(const file of files){if(/\.zip$/i.test(file.name)){const entries=await C.unzip(await file.arrayBuffer());for(const entry of entries.filter(f=>/\.json$/i.test(f.name)))incoming.push(...R.parse(JSON.parse(new TextDecoder().decode(entry.data))));}else incoming.push(...R.parse(JSON.parse(await file.text())));}if(!incoming.length)throw Error('文件中没有配方');await persist(R.merge(records,incoming));selectedId=records.at(-1).id;list();detail();document.getElementById('recipeExportAll').disabled=false;toast(`已导入 ${incoming.length} 份模板；同 ID 保留为独立副本`);}catch(err){toast('模板导入失败：'+err.message);}};
 document.getElementById('recipeExportAll').onclick=()=>download(JSON.stringify(R.bundle(records),null,2),'DanceCube-配方库-'+DCProject.timestamp()+'.json','application/json');
 list();detail();
}
root.DCRecipeUI={open,clear(){records=[];loaded=false;selectedId='';operation++;}};
})(window);
